const {spawnSync} = require('child_process');
const BIN = '/workspace/dataset/test4_executable';
function run(args, opts={}) {
  const r = spawnSync(opts.bin||BIN, args, {encoding:'buffer', env: opts.env||process.env, argv0: opts.argv0});
  return {
    code: r.status,
    signal: r.signal,
    out: r.stdout ? r.stdout.toString('hex') : '',
    outText: r.stdout ? r.stdout.toString('utf8') : '',
    err: r.stderr ? r.stderr.toString('hex') : '',
    errText: r.stderr ? r.stderr.toString('utf8') : '',
  };
}
module.exports = {run, BIN};
if (require.main === module) {
  const cases = JSON.parse(process.argv[2]);
  for (const c of cases) {
    const args = c.args !== undefined ? c.args : c;
    const r = run(args, c.opts||{});
    console.log(JSON.stringify({args, code:r.code, out:r.out, err:r.errText}));
  }
}
EOF
